+document.addEventListener('DOMContentLoaded', function() {
+    const quizForm = document.getElementById('quizForm');
+    const resultsSection = document.getElementById('resultsSection');
+    const resultsContent = document.getElementById('resultsContent');
+
+    quizForm.addEventListener('submit', function(e) {
+        e.preventDefault();
+        handleQuizSubmit();
+    });
+
+    function handleQuizSubmit() {
+        const answers = {
+            q1: getSelectedAnswers('q1'),
+            q2: getSelectedAnswers('q2'),
+            q3: getSelectedAnswers('q3')
+        };
+
+        displayResults(answers);
+    }
+
+    function getSelectedAnswers(questionName) {
+        const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
+        return Array.from(checkboxes).map(cb => cb.value);
+    }
+
+    function displayResults(answers) {
+        quizForm.style.display = 'none';
+        resultsSection.style.display = 'block';
+
+        const questions = [
+            { id: 'q1', text: 'Which of the following languages are statically typed?' },
+            { id: 'q2', text: 'Which languages run on the Java Virtual Machine (JVM)?' },
+            { id: 'q3', text: 'Which languages are primarily used for web development?' }
+        ];
+
+        let resultsHTML = '';
+
+        questions.forEach(question => {
+            const selectedAnswers = answers[question.id];
+            resultsHTML += `
+                <div class="result-question">
+                    <div class="result-question-title">${question.text}</div>
+                    ${selectedAnswers.length > 0 
+                        ? selectedAnswers.map(answer => `<div class="result-answer">${answer}</div>`).join('')
+                        : '<div class="no-answer">No answers selected</div>'
+                    }
+                </div>
+            `;
+        });
+
+        resultsContent.innerHTML = resultsHTML;
+    }
+});
+
')

