+    background: #e5e7eb;
+    color: #1f2937;
+    margin-top: 20px;
+}
+
+.reset-btn:hover {
+    background: #d1d5db;
+}
+
+.results-section {
+    padding: 40px;
+    animation: fadeIn 0.3s ease;
+}
+
+@keyframes fadeIn {
+    from {
+        opacity: 0;
+        transform: translateY(10px);
+    }
+    to {
+        opacity: 1;
+        transform: translateY(0);
+    }
+}
+
+.results-header {
+    text-align: center;
+    margin-bottom: 30px;
+}
+
+.results-header h2 {
+    font-size: 24px;
+    font-weight: 700;
+    color: #1f2937;
+    margin-bottom: 8px;
+}
+
+.results-message {
+    font-size: 14px;
+    color: #6b7280;
+}
+
+.results-content {
+    background: #f9fafb;
+    border-radius: 8px;
+    padding: 20px;
+    margin-bottom: 20px;
+    max-height: 400px;
+    overflow-y: auto;
+}
+
+.result-question {
+    margin-bottom: 20px;
+    padding-bottom: 20px;
+    border-bottom: 1px solid #e5e7eb;
+}
+
+.result-question:last-child {
+    border-bottom: none;
+    margin-bottom: 0;
+    padding-bottom: 0;
+}
+
+.result-question-title {
+    font-size: 14px;
+    font-weight: 600;
+    color: #1f2937;
+    margin-bottom: 10px;
+}
+
+.result-answer {
+    font-size: 13px;
+    color: #374151;
+    padding-left: 20px;
+    line-height: 1.8;
+}
+
+.result-answer::before {
+    content: '✓ ';
+    color: #667eea;
+    font-weight: 600;
+    margin-right: 6px;
+}
+
+.no-answer {
+    font-size: 13px;
+    color: #9ca3af;
+    padding-left: 20px;
+    font-style: italic;
+}
+
+.no-answer::before {
+    content: '○ ';
+    margin-right: 6px;
+}
+
+/* Responsive design */
+@media (max-width: 600px) {
+    .quiz-header {
+        padding: 30px 20px;
+    }
+
+    .quiz-header h1 {
+        font-size: 24px;
+    }
+
+    .quiz-form {
+        padding: 24px;
+    }
+
+    .form-field {
+        margin-bottom: 30px;
+        padding-bottom: 30px;
+    }
+
+    .question-title {
+        font-size: 16px;
+    }
+
+    .question-text {
+        font-size: 15px;
+    }
+
+    .submit-btn,
+    .reset-btn {
+        font-size: 14px;
+        padding: 12px 20px;
+    }
+
+    .results-section {
+        padding: 24px;
+    }
+}
+
")
